    uint8_t computeChecksum(const std::string& body) const {
        uint8_t checksum = 0;
        for (char c : talkerId_) {
            checksum ^= static_cast<uint8_t>(c);
        }
        for (char c : body) {
            checksum ^= static_cast<uint8_t>(c);
        }
        return checksum;
    }

    std::string buildSentence(const std::string& body) const {
        uint8_t cs = computeChecksum(body);
        std::ostringstream oss;
        oss << "$" << talkerId_ << body << "*" << std::hex << std::setw(2) << std::setfill('0') << int(cs);
        return oss.str();
    }

private:
    std::string talkerId_;
};

class GeodeticConverter {
public:
    GeodeticConverter(double semiMajorAxis, double flattening)
        : semiMajorAxis_(semiMajorAxis), flattening_(flattening) {}
    struct Geodetic { double lat, lon, alt; };

    Geodetic ecefToGeodetic(double x, double y, double z) const {
        double e2 = flattening_ * (2 - flattening_);
        double lon = std::atan2(y, x);
        double p = std::sqrt(x * x + y * y);
        double lat = std::atan2(z, p * (1 - e2));
        for (int i = 0; i < 5; ++i) {
            double sinLat = std::sin(lat);
            double n = semiMajorAxis_ / std::sqrt(1 - e2 * sinLat * sinLat);
            lat = std::atan2(z + e2 * n * sinLat, p);
        }
        double sinLat = std::sin(lat);
        double n = semiMajorAxis_ / std::sqrt(1 - e2 * sinLat * sinLat);
        double alt = p / std::cos(lat) - n;
        return {lat * 180.0 / M_PI, lon * 180.0 / M_PI, alt};
    }

private:
    double semiMajorAxis_;
    double flattening_;
};

