class RtcmStreamReader {
public:
    std::optional<RtcmMessage> readNextMessage() {
        uint8_t header[3];
        if (recv(socketFd_, header, sizeof(header), MSG_WAITALL) <= 0) return std::nullopt;
        if (header[0] != 0xD3) return std::nullopt;
        uint16_t length = ((header[1] & 0x03) << 8) | header[2];
        std::vector<uint8_t> payload(length);
        recv(socketFd_, payload.data(), length, MSG_WAITALL);
        return RtcmMessage{(payload[0] << 4) | (payload[1] >> 4), std::move(payload)};
    }

    void reconnect() {
        close(socketFd_);
        socketFd_ = connectToCaster(host_, port_);
        reconnectAttempts_++;
    }

private:
    int socketFd_;
    std::string host_;
    int port_;
    int reconnectAttempts_ = 0;
};

