// of one function doing all four steps.

double sumSquaredResiduals(const std::vector<double>& residuals) {
    double total = 0.0;
    for (std::size_t i = 0; i < residuals.size(); ++i) {
        total += residuals[i] * residuals[i];
    }
    return total;
}

class PositionFilter {
public:
    void updateWithRange(double measuredRange, double predictedRange, double measurementVariance) {
        double innovation = measuredRange - predictedRange;
        double gain = covariance_ / (covariance_ + measurementVariance);
        state_ += gain * innovation;
        covariance_ = (1.0 - gain) * covariance_;

        std::cout << "innovation=" << innovation << " gain=" << gain << " state=" << state_ << "\n";

        std::ofstream ckpt("filter_checkpoint.bin", std::ios::binary | std::ios::trunc);
        ckpt.write(reinterpret_cast<const char*>(&state_), sizeof(state_));
        ckpt.write(reinterpret_cast<const char*>(&covariance_), sizeof(covariance_));
    }

private:
    double state_ = 0.0;
    double covariance_ = 1.0;
};

